package com.bank.stages.scheduler;

// One logical operation tagged as narrow or wide (shuffle).
public class Operation {
    public enum Kind { NARROW, WIDE }
    private final String name;
    private final Kind kind;

    public Operation(String name, Kind kind) {
        this.name = name;
        this.kind = kind;
    }
    public String getName() { return name; }
    public boolean isWide() { return kind == Kind.WIDE; }
}
