package com.bank.stages.scheduler;

import java.util.ArrayList;
import java.util.List;

// A shuffle-free pipeline of operations plus its task count (= partitions).
public class Stage {
    private final int id;
    private final List<Operation> ops = new ArrayList<>();
    private int numPartitions;

    public Stage(int id, int numPartitions) {
        this.id = id;
        this.numPartitions = numPartitions;
    }
    public int getId() { return id; }
    public void addOp(Operation op) { ops.add(op); }
    public List<Operation> getOps() { return ops; }
    public int getNumPartitions() { return numPartitions; }
    public void setNumPartitions(int n) { this.numPartitions = n; }
    public int taskCount() { return numPartitions; } // one task per partition
}
