package com.bank.stages.scheduler;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Splits a pipeline into stages at every WIDE (shuffle) dependency.
public class DagScheduler {
    private static final Logger log = Logger.getLogger(DagScheduler.class.getName());

    // inputPartitions = partitions of the base data; shufflePartitions = post-shuffle count.
    public List<Stage> buildStages(List<Operation> pipeline,
                                   int inputPartitions, int shufflePartitions) {
        List<Stage> stages = new ArrayList<>();
        Stage current = new Stage(0, inputPartitions);
        stages.add(current);

        for (Operation op : pipeline) {
            if (op.isWide()) {
                // Shuffle boundary: close current stage, start a new one.
                log.info(() -> "WIDE op '" + op.getName()
                        + "' => stage boundary (shuffle). Starting new stage.");
                current = new Stage(stages.size(), shufflePartitions);
                stages.add(current);
                current.addOp(op); // the wide op belongs to the new (reduce) stage
            } else {
                log.fine(() -> "NARROW op '" + op.getName() + "' pipelined into stage "
                        + current.getId());
                current.addOp(op);
            }
        }
        // Report the stage graph.
        for (Stage s : stages) {
            log.info(() -> "Stage " + s.getId() + ": ops=" + opNames(s)
                    + ", tasks=" + s.taskCount() + " (one per partition)");
        }
        return stages;
    }

    private String opNames(Stage s) {
        List<String> names = new ArrayList<>();
        for (Operation o : s.getOps()) names.add(o.getName());
        return names.toString();
    }
}
