package com.bank.stages;

import com.bank.stages.scheduler.*;
import java.util.List;
import java.util.logging.*;

public class StagesDemo {
    private static final Logger log = Logger.getLogger(StagesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new StagesLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Pipeline: filter(narrow) -> map(narrow) -> groupByKey(WIDE) -> aggregate(narrow)
        List<Operation> pipeline = List.of(
            new Operation("filter(SAV2001|CUR3001)", Operation.Kind.NARROW),
            new Operation("map(amount)",             Operation.Kind.NARROW),
            new Operation("groupByKey(accountId)",   Operation.Kind.WIDE),
            new Operation("aggregate(sum)",          Operation.Kind.NARROW)
        );

        DagScheduler scheduler = new DagScheduler();
        List<Stage> stages = scheduler.buildStages(pipeline, 4, 3);

        log.info(() -> "Total stages = " + stages.size()
                + " (one shuffle => two stages)");
    }
}

